#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<int> numbers = {1, 3, 5, 7, 9};
    // Predicate to check if a number is even
    auto is_even = [](int n) { return n % 2 == 0; };
    // Use std::none_of to check if no elements are even
    bool result = std::none_of(numbers.begin(), numbers.end(), is_even);
    std::cout << "Are there no even numbers? " << (result ? "Yes" : "No") << std::endl;
    return 0;
}
